typedef unsigned int u_int;

template <class T> inline const T& min(const T& a, const T& b)
{
	return b < a ? b : a;
}

template <int n> struct SplineCoeffs {
	float a[n], b[n], c[n], d[n];
};

inline u_int SPLINE_BinarySearch(const float *x, u_int n, const float &valx)
{
	u_int lo = 0, hi = n - 1, mid;
	while (hi - lo > 1)
	{
		mid = (lo + hi) / 2;
		if (x[mid] < valx) lo = mid;
		else hi = mid;
	}

	return lo;
}

inline float SPLINE_Evaluate(const float *x, const float *a, const float *b, const float *c, const float *d,
	u_int n, float valx)
{
	u_int lo = SPLINE_BinarySearch(x, n, valx);
	valx -= x[lo];
	return ((a[lo] * valx + b[lo]) * valx + c[lo]) * valx + d[lo];
}

extern void SPLINE_ComputeCoeffs(const float *, const float *, int, float *, float *, float *, float *);
extern float WAVE_ArtToProfile(float x);

struct WaveControlPoints {
	char data[0x2404];
	u_int numprofile;
};

extern WaveControlPoints *WAVE_ControlPoints;
extern float WAVE_ProfileX[16];
extern SplineCoeffs<16> WAVE_ProfileToWorldCoeffs;

__asm__(".equ WAVE_ControlPoints, 0x004846F0");
__asm__(".equ WAVE_ProfileX, 0x00585980");
__asm__(".equ WAVE_ProfileToWorldCoeffs, 0x00585C70");

struct WavePartition {
	u_int N;
	float *guide;
	float *guidestep;
	float *weight;
};

enum WavePerturbStageEnum {
	WAVE_PerturbStageNone,
	WAVE_PerturbStageDo,
	WAVE_PerturbStageHold,
	WAVE_PerturbStageCollapse,
	WAVE_PerturbStageWait,
	WAVE_PerturbStageUndo,
	WAVE_PerturbStageMax
};

class WaveBasePerturbClass {
public:
	float (&duration)[WAVE_PerturbStageMax], start[WAVE_PerturbStageMax];
	WavePartition partition;
	virtual void Init(void) = 0;
	virtual float WorldToProfile(float worldx) = 0;
protected:
	const int &enabled;
private:
	float guide[32];
	float guidestep[32];
	float weight[32];
};

template <int n> class WavePerturbClass : public WaveBasePerturbClass {
public:
	const static u_int num;
	virtual void Init(void) = 0;
	virtual float WorldToProfile(float worldx) = 0;
};

template <int n> const u_int WavePerturbClass<n>::num = n;

template <int n> class WavePulsePerturbClass : public WavePerturbClass<n> {
public:
	const float (&pulse)[n];
	float profilelo, profilehi;
	float pulsex[n], pulsexx[n];
	SplineCoeffs<n> pulsecoeffs;
	float offset;
	virtual void Init(void);
	virtual float WorldToProfile(float worldx);
	virtual float WorldToPulse(float worldx);
};

template <int n> class WaveProfilePerturbClass : public WavePulsePerturbClass<n> {
public:
	const float (&profilex)[n], (&profilexx)[n];
	float x[n], xx[n];
	SplineCoeffs<n> coeffs;
	float shift;
	virtual void Init(void);
	virtual float WorldToProfile(float worldx) = 0;
};

template <int n> void WaveProfilePerturbClass<n>::Init(void)
{
	// Set up spline
	shift = 0;
	for (u_int i = 0; i < num; ++i)
	{
		x[i] = SPLINE_Evaluate(WAVE_ProfileX,
			WAVE_ProfileToWorldCoeffs.a,
			WAVE_ProfileToWorldCoeffs.b,
			WAVE_ProfileToWorldCoeffs.c,
			WAVE_ProfileToWorldCoeffs.d,
			WAVE_ControlPoints->numprofile, WAVE_ArtToProfile(profilex[i]));
		xx[i] = SPLINE_Evaluate(WAVE_ProfileX,
			WAVE_ProfileToWorldCoeffs.a,
			WAVE_ProfileToWorldCoeffs.b,
			WAVE_ProfileToWorldCoeffs.c,
			WAVE_ProfileToWorldCoeffs.d,
			WAVE_ControlPoints->numprofile, WAVE_ArtToProfile(profilexx[i]));
		shift = min(shift, xx[i] - x[i]);
	}

	SPLINE_ComputeCoeffs(x, xx, num, coeffs.a, coeffs.b, coeffs.c, coeffs.d);

	WavePulsePerturbClass<n>::Init();
}

template void WaveProfilePerturbClass<6>::Init(void);
